import json
def analyze(n):
    i=G['D%d_input'%n]; o=G['D%d_output'%n]
    S6={(r,c) for r in range(4) for c in range(4) if i[r][c]==6}
    S5={(r,c) for r in range(4) for c in range(8) if i[r][c]==5}
    best=[]
    for dr in range(-4,5):
        for dc in range(-8,9):
            tS6={(r+dr,c+dc) for r,c in S6}
            cov=tS6&S5
            miss=S5-tS6
            # coverage score
            best.append((-(len(S5)-len(cov)),dr,dc,len(miss)))
    best.sort()
    print('D'+str(n),'best shift',best[0])
    return best[0][:2]
for n in [1,2,3]:
    analyze(n)

